use anyhow::{Result, bail};
use std::ffi::OsString;

/// A uutils utility's entry point.
type Main = fn(std::vec::IntoIter<OsString>) -> i32;

// `APPLETS`, generated by build.rs from the uu_* dependencies in Cargo.toml.
include!(concat!(env!("OUT_DIR"), "/applets.rs"));

pub fn names() -> impl Iterator<Item = &'static str> {
    APPLETS.iter().map(|&(name, _)| name)
}

pub fn is_applet(name: &str) -> bool {
    names().any(|applet| applet == name)
}

pub fn run(name: &str, args: Vec<OsString>) -> Result<i32> {
    let Some(&(_, main)) = APPLETS.iter().find(|&&(applet, _)| applet == name) else {
        bail!("unknown coreutils applet {name:?}");
    };
    // As in uutils' own multicall binary, `[` speaks for test, and dir and
    // vdir for ls.
    let messages = match name {
        "[" => "test",
        "dir" | "vdir" => "ls",
        _ => name,
    };
    uucore::locale::setup_localization(messages)?;
    Ok(main(args.into_iter()))
}
